public void triggerRecurrentEffect(BlobItem blobItem) {
    if (blobItem.getHitpoints() <= this.srcInitialHitpoints) {
        blobItem.setHitpoints(this.srcInitialHitpoints);
    } else {
        blobItem.setHitpoints(blobItem.getHitpoints() - AGGRESSIVE_DAMAGE_DECREMENT);
    }
}
